	b := BackoffConfig{
		MaxDelay:   DefaultBackoffConfig.MaxDelay / 2,
		BaseDelay:  500 * time.Millisecond,
		Multiplier: 2,
		Jitter:     0.1,
	}
	expected := b
	testBackoffConfigSet(t, &expected, WithBackoffConfig(b))
}

